{
  "caseId": "HYEOB-20261112-001",
  "decision": "분류번호와 재활용 경로 확정 보류",
  "reasons": [
    "HDPE 압출 자투리 분쇄물이라는 입력은 시험용 가정이며, 현장 사실로 검증되지 않았다.",
    "51-03-01은 사업장일반폐기물에 해당하고 지정폐기물이 아닌 PVC 제외 폐합성수지류로 확인될 경우 검토할 수 있는 분류번호다.",
    "R-3-3은 가능한 재활용 유형에 열거되어 있으나, 입력된 발생 공정만으로 실제 재활용 공정과 산출물의 적합성을 판단할 수 없다."
  ],
  "evidence": [
    {
      "sourceId": "legal-291947-annex4-code",
      "locator": "별표 4 제2호 51-03-01, PDF 6쪽",
      "supports": "조건부 분류번호 검토"
    },
    {
      "sourceId": "legal-291947-annex4-2-r3-3",
      "locator": "별표 4의2 제2호가목3), PDF 1쪽",
      "supports": "R-3-3의 정의"
    },
    {
      "sourceId": "legal-291947-annex4-3-types",
      "locator": "별표 4의3 제2호 51-03-01, PDF 9쪽",
      "supports": "51-03-01에 열거된 재활용 유형에 R-3-3 포함"
    },
    {
      "sourceId": "legal-291947-annex5-3-common",
      "locator": "별표 5의3 제1호다목, PDF 1쪽",
      "supports": "재활용 유형별 세부기준 준수 필요"
    }
  ],
  "limitations": [
    "사진이 없으며 수지, 오염·유해물질 접촉 여부, 질량 및 발생 장소는 검증되지 않았다.",
    "사업장일반폐기물 해당 여부와 지정폐기물 제외 여부를 확인해야 한다.",
    "실제 재활용 공정·산출물·용도, 세부기준, 허가 범위 및 인수 조건을 확인해야 한다.",
    "재활용환경성평가 예외, 금지·제한, 별표 5의4 준수사항 및 경과조치 적용 여부는 확인되지 않았다."
  ]
}

{
  "caseId": "HYEOB-20261112-002",
  "decision": "분류번호와 재활용 경로 확정 보류",
  "reasons": [
    "PET 성형 자투리이며 오염과 유해물질 접촉이 없다는 내용은 검증용 가정이다. 사진이나 현장 확인 자료가 없다.",
    "51-03-01 적용에는 사업장일반폐기물 해당 여부와 지정폐기물 제외 확인이 필요하다.",
    "R-3-3은 가능한 재활용 유형으로 열거되어 있으나, 실제 재활용 공정·산출물·용도가 제시되지 않아 이 사례에 적용할 수 없다."
  ],
  "evidence": [
    {
      "sourceId": "legal-291947-annex4-code",
      "finding": "사업장일반폐기물로 확인된 PVC 제외 폐합성수지류의 분류번호는 51-03-01이다."
    },
    {
      "sourceId": "legal-291947-annex4-2-r3-3",
      "finding": "R-3-3은 선별 등으로 폐기물을 합성수지 등의 원료물질로 제조하는 재활용 유형이다."
    },
    {
      "sourceId": "legal-291947-annex4-3-types",
      "finding": "51-03-01의 재활용 가능 유형에 R-3-3이 포함된다."
    },
    {
      "sourceId": "legal-291947-annex5-3-common",
      "finding": "해당 재활용 유형의 세부기준도 준수해야 한다."
    }
  ],
  "limitations": [
    "사진이 없으며 공정·수지·오염·접촉·질량·지역은 모두 가정값이다.",
    "실제 폐기물 분류, 재활용 공정과 산출물, 세부기준, 허가 범위 및 인수 조건은 확인되지 않았다.",
    "재활용환경성평가 예외, 금지·제한, 별표 5의4 준수사항 및 경과조치 적용 여부는 확인되지 않았다."
  ]
}

{
  "caseId": "HYEOB-20261112-003",
  "decision": "판정 보류",
  "reasons": [
    "입력 내용은 검증 목적의 가정이며 사진이나 현장 확인 자료가 없다.",
    "제공된 일반 조문만으로 폐기물 세부분류 코드나 재활용 처리경로의 적합성을 판단할 수 없다."
  ],
  "evidence": [
    {
      "sourceId": "waste-rule-2026-11-12",
      "locator": "제4조의2 제1항",
      "finding": "폐기물의 종류별 세부분류는 별표 4에 따른다."
    },
    {
      "sourceId": "legal-291947-annex5-3-common",
      "locator": "별표 5의3 제1호다목",
      "finding": "해당 예외를 제외한 재활용에는 별표 4의3의 가능 유형과 유형별 세부기준 준수가 요구된다."
    }
  ],
  "limitations": [
    "별표 4의 해당 코드, 별표 4의3의 가능 유형 및 구체적인 처리기준은 제공되지 않았다.",
    "재활용환경성평가 예외, 금지·제한, 별표 5의4 준수사항 및 현행 허가를 확인하지 못했다.",
    "용도·이전 신고·분류 변경 이력이 없어 경과조치 적용 여부를 확인하지 못했다.",
    "수지 구성, 오염 여부, 유해물질 접촉 여부 및 질량은 현장 사실로 검증되지 않았다."
  ]
}

{
  "caseId": "HYEOB-20261112-004",
  "decision": "분류 및 재활용 경로 판정 보류",
  "reasons": [
    "이전 내용물과 잔류물이 확인되지 않아 세척 완료 및 유해물질 접촉 없음이라는 입력만으로 오염·위해 여부를 확정할 수 없습니다.",
    "HDPE 재질, 세척·압축 공정, 질량·지역은 시험용 가정이며 현장 사실로 검증되지 않았습니다. 사진도 제공되지 않았습니다.",
    "제공된 일반 조문만으로 폐기물 세부분류 코드나 특정 재활용 유형의 적합성을 판정할 수 없습니다."
  ],
  "evidence": [
    {
      "sourceId": "waste-rule-2026-11-12",
      "locator": "제4조의2 제1항",
      "relevance": "폐기물 세부분류는 별표 4에 따른다고 규정합니다. 개별 코드는 제시하지 않습니다."
    },
    {
      "sourceId": "legal-291947-annex5-3-common",
      "locator": "별표 5의3 제1호다목",
      "relevance": "해당 재활용자는 별표 4의3의 가능 유형과 유형별 세부기준을 함께 준수해야 한다는 일반 기준입니다."
    }
  ],
  "limitations": [
    "이전 내용물·잔류물, 실제 재질과 공정, 현장 사진이 확인되지 않았습니다.",
    "별표 4의 해당 코드, 별표 4의3의 가능 유형, 금지·제한 사항, 별표 5의4 준수사항 및 현행 허가를 확인해야 합니다.",
    "재활용환경성평가 예외 해당 여부와 이전 신고·분류 변경 이력이 없어 경과조치 적용 여부도 판단할 수 없습니다."
  ]
}

{
  "caseId": "HYEOB-20261112-005",
  "decision": "판정 보류: 폐기물 세부분류와 냉간 압축 후 재활용 경로의 적합성을 확인할 수 없음",
  "reasons": [
    "입력은 시험용 가정이며 사진이 없어 재질 혼합 상태와 테이프·접착제 부착 정도를 확인할 수 없다.",
    "유해물질 접촉 여부가 불명이고 질량·지역 정보가 없다.",
    "제공된 일반 조문만으로 이 폐기물의 개별 분류코드나 재활용 유형의 적합성을 판단할 수 없다."
  ],
  "evidence": [
    {
      "sourceId": "waste-rule-2026-11-12",
      "locator": "제4조의2 제1항",
      "finding": "폐기물의 종류별 세부분류는 별표 4에 따른다."
    },
    {
      "sourceId": "legal-291947-annex5-3-common",
      "locator": "별표 5의3 제1호다목",
      "finding": "적용 대상 재활용자는 별표 4의3의 재활용 가능 유형과 유형별 세부기준을 함께 준수해야 한다."
    }
  ],
  "limitations": [
    "별표 4의 해당 분류, 별표 4의3의 해당 유형, 관련 세부기준의 사례별 적용 근거가 제공되지 않았다.",
    "재활용환경성평가 예외, 금지·제한, 별표 5의4 준수사항 및 현행 허가를 확인하지 못했다.",
    "용도·이전 신고·분류 변경 이력이 없어 부칙 제18호 제3조의 경과조치 적용 여부를 확인하지 못했다."
  ]
}

{
  "caseId": "HYEOB-20261112-006",
  "decision": "재활용 경로 적합성 판단 보류",
  "reasons": [
    "PET 결속밴드라는 입력만으로 사업장일반폐기물 해당 여부와 지정폐기물 제외 여부를 확정할 수 없어 폐기물 코드도 확정할 수 없다.",
    "R-3-3은 가능한 재활용 유형으로 열거되어 있으나, 입력된 ‘결속밴드 절단’이 실제 재활용 공정인지, 산출물이 원료물질인지 확인되지 않았다.",
    "인수 업체의 허가 범위와 인수 조건이 확인되지 않았다."
  ],
  "evidence": [
    {
      "sourceId": "legal-291947-annex4-code",
      "finding": "별표 4의 51-03-01은 PVC를 제외한 폐합성수지류의 분류번호다. 이 사례에 대한 적용은 미확정이다."
    },
    {
      "sourceId": "legal-291947-annex4-2-r3-3",
      "finding": "R-3-3은 절단 등을 통해 폐기물을 합성수지 등의 원료물질로 제조하는 유형이다."
    },
    {
      "sourceId": "legal-291947-annex4-3-types",
      "finding": "51-03-01 행에 R-3-3이 열거되어 있다."
    },
    {
      "sourceId": "legal-291947-annex5-3-common",
      "finding": "해당 재활용 유형의 세부기준도 준수해야 한다."
    }
  ],
  "limitations": [
    "사진이 없으며, 공정·재질·오염·유해물질 접촉 여부·질량·지역은 검증용 가정이지 확인된 현장 사실이 아니다.",
    "실제 재활용 공정·산출물·용도, 유형별 세부기준, 허가 범위, 인수 조건 및 관련 예외·제한사항은 확인되지 않았다."
  ]
}

{
  "caseId": "HYEOB-20261112-007",
  "decision": "판정 보류: HDPE 운반 상자의 재사용 가능성과 폐기물 재활용 경로의 적법성을 확인할 자료가 부족합니다.",
  "reasons": [
    "공정·재질·오염 여부 등은 시험용 가정이며, 실물 사진이나 상태 확인 자료가 없습니다.",
    "상자를 그대로 재사용하는지 폐기물로 분류해 재활용하는지 확정되지 않았습니다.",
    "제공된 일반 조문만으로 개별 폐기물 코드나 재활용 유형의 적합성을 판단할 수 없습니다."
  ],
  "evidence": [
    {
      "sourceId": "waste-rule-2026-11-12",
      "locator": "제4조의2 제1항",
      "finding": "폐기물의 종류별 세부분류는 별표 4에 따릅니다."
    },
    {
      "sourceId": "legal-291947-annex5-3-common",
      "locator": "별표 5의3 제1호다목",
      "finding": "해당하는 재활용자는 별표 4의3의 가능 유형과 별표 5의3의 유형별 세부기준을 함께 준수해야 합니다."
    }
  ],
  "limitations": [
    "사진이 없고, 오염·유해물질 접촉 여부와 30kg이라는 질량도 검증되지 않았습니다.",
    "해당 폐기물 코드·재활용 유형, 재활용환경성평가 예외와 금지·제한, 별표 5의4 준수사항 및 현행 허가를 확인해야 합니다.",
    "용도·이전 신고·분류 변경 이력이 없어 부칙 제18호 제3조 경과조치 적용 여부를 판단할 수 없습니다."
  ]
}

{
  "caseId": "HYEOB-20261112-008",
  "decision": "분류 및 재활용 경로 판단 보류",
  "reasons": [
    "입력은 검증 목적의 가정이며 실제 현장 사실로 확인되지 않았다.",
    "폐유의 접촉 물질과 잔류 정도가 확인되지 않았고, 사진도 제공되지 않았다.",
    "제공된 근거는 개별 폐기물 코드나 재활용 경로의 적합성을 입증하지 않는다."
  ],
  "evidence": [
    {
      "sourceId": "waste-rule-2026-11-12",
      "finding": "폐기물의 종류별 세부분류는 별표 4에 따른다."
    },
    {
      "sourceId": "legal-291947-annex5-3-common",
      "finding": "해당 재활용자는 재활용 가능 유형과 유형별 세부기준을 함께 준수해야 한다."
    }
  ],
  "limitations": [
    "별표 4의 개별 코드, 별표 4의3의 가능 유형 및 해당 세부기준은 제공된 근거로 확인되지 않았다.",
    "재활용환경성평가 예외, 금지·제한, 별표 5의4 준수사항 및 현행 허가를 확인해야 한다.",
    "용도·이전 신고·분류 변경 이력이 없어 경과조치 적용 여부를 판단할 수 없다.",
    "‘hazardousContact: no’는 입력값일 뿐, 미확인 오염 상태를 해소하는 증거는 아니다."
  ]
}

{
  "decision": "분류 및 재활용 적합성 판단 보류",
  "reasons": [
    "시험용 입력으로, 발생원·수지·질량 등 현장 사실이 확인되지 않았고 사진도 제공되지 않았다.",
    "공정, 오염 상태, 유해물질 접촉 여부, 지역이 확인되지 않았다.",
    "제공된 일반 조문만으로는 폐기물 세부분류 코드나 재활용 경로의 적합성을 판단할 수 없다."
  ],
  "evidence": [
    {
      "sourceId": "waste-rule-2026-11-12",
      "finding": "폐기물 종류별 세부분류는 별표 4에 따른다."
    },
    {
      "sourceId": "legal-291947-annex5-3-common",
      "finding": "해당 재활용자는 별표 4의3의 가능 유형과 별표 5의3의 유형별 세부기준을 함께 준수해야 한다. 재활용환경성평가를 받은 경우의 예외가 명시돼 있다."
    }
  ],
  "limitations": [
